#include <bits/stdc++.h>
using namespace std;
using llong = long long;
using PII = pair<int, int>;

char field1[15][15], field2[15][15];
const int dr[4] = {-1, 1, 0, 0};
const int dc[4] = {0, 0, -1, 1};
int nodeId[65][15][15];
int distFromZ[15][15];
int nextNodeId = 1;

struct FlowEdge {
    int from, to;
    llong capacity, flow;
    FlowEdge(int f, int t, llong c) : from(f), to(t), capacity(c), flow(0) {}
};

struct DinicMaxFlow {
    int nodes;
    vector<FlowEdge> edgeList;
    vector<vector<int>> adjacency;
    vector<int> level, nextEdge;

    DinicMaxFlow(int n) : nodes(n), edgeList(), adjacency(n), level(n), nextEdge(n) {}

    void insertEdge(int u, int v, llong cap) {
        if (u == v) return;
        edgeList.emplace_back(u, v, cap);
        adjacency[u].push_back(edgeList.size() - 1);
        edgeList.emplace_back(v, u, 0);
        adjacency[v].push_back(edgeList.size() - 1);
    }

    bool createLevelGraph(int source, int sink) {
        fill(level.begin(), level.end(), nodes + 1);
        queue<int> q;
        q.push(source);
        level[source] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (u == sink) break;
            for (int idx : adjacency[u]) {
                FlowEdge &e = edgeList[idx];
                if (e.flow < e.capacity && level[e.to] > level[e.from] + 1) {
                    level[e.to] = level[e.from] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[sink] <= nodes;
    }

    llong push(int u, int sink, llong bottleneck) {
        if (u == sink || bottleneck == 0) return bottleneck;
        for (int &i = nextEdge[u]; i < (int)adjacency[u].size(); ++i) {
            FlowEdge &e = edgeList[adjacency[u][i]];
            if (level[e.to] == level[e.from] + 1) {
                llong available = e.capacity - e.flow;
                if (bottleneck != -1 && available > bottleneck) available = bottleneck;
                llong pushed = push(e.to, sink, available);
                if (pushed > 0) {
                    e.flow += pushed;
                    edgeList[adjacency[u][i] ^ 1].flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    llong computeMaxFlow(int source, int sink) {
        llong total = 0;
        while (createLevelGraph(source, sink)) {
            fill(nextEdge.begin(), nextEdge.end(), 0);
            llong pushed;
            while ((pushed = push(source, sink, -1)) > 0) {
                total += pushed;
            }
        }
        return total;
    }
};

int main() {
    memset(distFromZ, -1, sizeof(distFromZ));
    int n, t;
    cin >> n >> t;
    for (int i = 1; i <= n; ++i) {
        cin >> (field1[i] + 1);
    }
    for (int layer = 0; layer <= t + 1; ++layer) {
        for (int row = 1; row <= n; ++row) {
            for (int col = 1; col <= n; ++col) {
                nodeId[layer][row][col] = nextNodeId++;
            }
        }
    }
    nextNodeId++;
    for (int i = 1; i <= n; ++i) {
        cin >> (field2[i] + 1);
    }
    queue<PII> q;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (field1[i][j] == 'Z') {
                q.emplace(i, j);
                distFromZ[i][j] = 0;
            }
        }
    }
    while (!q.empty()) {
        auto [y, x] = q.front(); q.pop();
        for (int d = 0; d < 4; ++d) {
            int ny = y + dr[d], nx = x + dc[d];
            if (ny >= 1 && ny <= n && nx >= 1 && nx <= n && field1[ny][nx] != 'Y' && distFromZ[ny][nx] == -1) {
                distFromZ[ny][nx] = distFromZ[y][x] + 1;
                q.emplace(ny, nx);
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (distFromZ[i][j] == -1) distFromZ[i][j] = 1e9;
            if (distFromZ[i][j] > t) distFromZ[i][j] = 1e9;
        }
    }
    int sourceNode = 0, sinkNode = nextNodeId - 1;
    DinicMaxFlow flowNet(nextNodeId);
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (field1[i][j] >= '1' && field1[i][j] <= '9') {
                flowNet.insertEdge(sourceNode, nodeId[0][i][j], field1[i][j] - '0');
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (field1[i][j] == 'Y' || field1[i][j] == 'Z') continue;
            for (int d = 0; d < 4; ++d) {
                int ny = i + dr[d], nj = j + dc[d];
                if (ny >= 1 && ny <= n && nj >= 1 && nj <= n && field1[ny][nj] != 'Y' && field1[ny][nj] != 'Z') {
                    for (int step = 0; step < t; ++step) {
                        if (distFromZ[ny][nj] >= step + 1 && distFromZ[i][j] > step) {
                            flowNet.insertEdge(nodeId[step][i][j], nodeId[step + 1][ny][nj], 1000);
                        }
                    }
                }
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (field1[i][j] == 'Y' || field1[i][j] == 'Z') continue;
            for (int step = 0; step <= t; ++step) {
                if (field2[i][j] >= '1' && field2[i][j] <= '9') {
                    flowNet.insertEdge(nodeId[step][i][j], nodeId[t + 1][i][j], field2[i][j] - '0');
                }
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (field1[i][j] == 'Y' || field1[i][j] == 'Z') continue;
            if (field2[i][j] >= '1' && field2[i][j] <= '9') {
                flowNet.insertEdge(nodeId[t + 1][i][j], sinkNode, field2[i][j] - '0');
            }
        }
    }
    cout << (int)flowNet.computeMaxFlow(sourceNode, sinkNode) << '\n';
    return 0;
}
